'use strict';

const {
    Strongmb,
    ApiError,
    AuthError,
    StrongmbError
} = require('../src/index');

const strongmb = new Strongmb('your_api_key_here');


(async () => {

    // ── Get data plans / product codes ────────────────────────────────────────────
    try {
        const response = await strongmb.data.plans();

        for (const biller of response.data().billers) {
            console.log(biller.name);

            for (const [productType, product] of Object.entries(biller.products)) {
                console.log('  ' + productType.toUpperCase());

                for (const plan of product.plans) {
                    const size = plan.bundle_size_mb >= 1024 ?
                        (plan.bundle_size_mb / 1024).toFixed(1) + 'GB' :
                        plan.bundle_size_mb + 'MB';

                    console.log(`    [${plan.product_code}] ${size} — ₦${plan.amount.toLocaleString()} / ${plan.validity}`);
                }
            }

            console.log('');
        }
    } catch (err) {
        if (err instanceof ApiError) {
            console.error('Error:', err.message);
        }
    }




    // ── Purchase a data plan ──────────────────────────────────────────────────────
    try {
        const response = await strongmb.data.purchase({
            phone: '08012345678',
            productCode: 'smb_air_sme_ec9e4',
            reference: 'MYAPP' + Date.now(),
        });

        if (response.successful()) {
            const data = response.data();
            console.log('Data sent!');
            console.log('Provider: ', data.provider);
            console.log('Recipient:', data.recipient);
            console.log('Plan:     ', data.plan, '(' + data.data_type + ')');
            console.log('Validity: ', data.validity);
            console.log('Amount:   ₦' + data.amount.toLocaleString());
            console.log('Reference:', data.reference);
            console.log('Balance:  ₦' + data.balance_after.toLocaleString());

        } else if (response.processing()) {
            console.log('Processing — poll by reference to check status.');
            console.log('Reference:', response.data().reference);

        } else if (response.failed()) {
            console.log('Transaction failed. Check status and contact support if wallet was debited.');
            console.log('Reference:', response.data().reference);
        }
    } catch (err) {
        if (err instanceof AuthError) {
            console.error('Invalid API key.');
        } else if (err instanceof ApiError) {
            console.error(`Error [${err.getApiCode()}]: ${err.message}`);
            console.error('Trace ID:', err.getTraceId());
        } else if (err instanceof StrongmbError) {
            console.error('Network error:', err.message);
        }
    }

})();